use syn::{Expr, Pat, Stmt};

use crate::{node_type_set::NodeTypeSet, utils::astkind_variant_from_path};

/// Fetches the current list of variants that are handled by `run_on_regex_node`.
/// We read the source file to avoid hardcoding the list here and ensure this will stay updated.
pub fn get_regex_node_kinds() -> Option<NodeTypeSet> {
    // Read crates/oxc_linter/src/utils/regex.rs and extract all variants in `run_on_regex_node` function
    let regex_utils_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()?
        .parent()?
        .join("crates")
        .join("oxc_linter")
        .join("src")
        .join("utils")
        .join("regex.rs");
    let content = std::fs::read_to_string(regex_utils_path).ok()?;
    let syntax = syn::parse_file(&content).ok()?;
    let mut node_type_set = NodeTypeSet::new();
    for item in syntax.items {
        if let syn::Item::Fn(func) = item
            && func.sig.ident == "run_on_regex_node"
        {
            // Look for `match node.kind() { ... }` inside the function body
            for stmt in &func.block.stmts {
                if let Stmt::Expr(Expr::Match(match_expr), _) = stmt {
                    for arm in &match_expr.arms {
                        let pat = match &arm.pat {
                            Pat::Guard(guard) => guard.pat.as_ref(),
                            pat => pat,
                        };
                        if let Pat::TupleStruct(ts) = pat
                            && let Some(variant) = astkind_variant_from_path(&ts.path)
                        {
                            node_type_set.insert(variant);
                        }
                    }
                    if !node_type_set.is_empty() {
                        return Some(node_type_set);
                    }
                }
            }
        }
    }
    None
}

use std::path::Path;

use convert_case::{Case, Casing};

/// Represents a lint rule entry in the `declare_all_lint_rules!` macro.
#[derive(PartialEq, Eq, PartialOrd, Ord)]
pub struct RuleEntry<'e> {
    /// The module name of the rule's plugin, like `eslint` in `eslint::no_debugger::NoDebugger`.
    pub plugin_module_name: &'e str,
    /// The rule's module name, like `no_debugger` in `eslint::no_debugger:NoDebugger`.
    pub rule_module_name: &'e str,
    /// Whether the rule overrides `Rule::from_configuration`.
    pub has_custom_from_configuration: bool,
    /// Whether the rule overrides `Rule::to_configuration`.
    pub has_custom_to_configuration: bool,
}

impl RuleEntry<'_> {
    /// Get the rule's struct name, like `NoDebugger` in `eslint::no_debugger::NoDebugger`.
    pub fn rule_struct_name(&self) -> String {
        self.rule_module_name.to_case(Case::Pascal)
    }
}

/// Parses `crates/oxc_linter/src/rules.rs` to extract all lint rule declarations into a list
/// of `RuleEntry` by scanning the module declarations.
pub fn get_all_rules(contents: &str) -> Vec<RuleEntry<'_>> {
    let mut rule_entries = Vec::new();
    let mut current_plugin: Option<&str> = None;

    for line in contents.lines() {
        let line = line.trim();

        // Detect plugin module start: `pub(crate) mod eslint {` or `pub(crate) mod typescript {`
        if line.starts_with("pub(crate) mod ") && line.ends_with(" {") {
            let module_name =
                line.strip_prefix("pub(crate) mod ").and_then(|s| s.strip_suffix(" {"));
            current_plugin = module_name;
            continue;
        }

        // Detect end of plugin module
        if line == "}" {
            current_plugin = None;
            continue;
        }

        // Inside a plugin module, detect rule module: `pub mod no_debugger;`
        if let Some(plugin) = current_plugin
            && plugin != "shared"
            && line.starts_with("pub mod ")
            && line.ends_with(';')
            && let Some(rule_name) = line.strip_prefix("pub mod ").and_then(|s| s.strip_suffix(';'))
        {
            rule_entries.push(RuleEntry {
                plugin_module_name: plugin,
                rule_module_name: rule_name,
                // Preserve the existing generated behavior unless codegen confirms that the rule
                // uses the default implementation.
                has_custom_from_configuration: true,
                has_custom_to_configuration: true,
            });
        }
    }

    // Preserve declaration order - do not sort
    rule_entries
}

/// Given a rule entry, attempt to find its corresponding source file path
pub fn find_rule_source_file(root: &Path, rule: &RuleEntry) -> Option<std::path::PathBuf> {
    // A rule path corresponds to:
    // 1) `crates/oxc_linter/src/rules/<plugin>/<rule>.rs`
    // 2) `crates/oxc_linter/src/rules/<plugin>/<rule>/mod.rs`
    let rules_path = root.join("crates/oxc_linter/src/rules").join(rule.plugin_module_name);

    let direct_path = rules_path.join(format!("{}.rs", rule.rule_module_name));
    if direct_path.exists() {
        return Some(direct_path);
    }

    let mod_path = rules_path.join(rule.rule_module_name).join("mod.rs");
    if mod_path.exists() {
        return Some(mod_path);
    }

    None
}

use convert_case::{Case, Casing};
use proc_macro2::{Ident, Span, TokenStream};
use quote::quote;

use crate::rules::RuleEntry;

/// Generate the RuleEnum and related code that replaces `declare_all_lint_rules!` macro.
pub fn generate_rules_enum(rule_entries: &[RuleEntry<'_>]) -> String {
    let header = quote! {
        #![expect(
            clippy::default_constructed_unit_structs,  // Many rules are unit structs
            clippy::semicolon_if_nothing_returned,     // Match arms in void-returning methods
            clippy::wrong_self_convention,             // from_configuration takes &self
            clippy::missing_errors_doc,                // Generated code
            clippy::match_same_arms,                   // plugin_name() has many same-body arms
        )]
    };

    let use_statements = generate_use_statements(rule_entries);
    let imports = generate_imports();
    let rule_enum = generate_rule_enum(rule_entries);
    let id_constants = generate_id_constants(rule_entries);
    let rule_enum_impl = generate_rule_enum_impl(rule_entries);
    let trait_impls = generate_trait_impls();
    let rules_static = generate_rules_static(rule_entries);

    let tokens = quote! {
        #header

        #use_statements

        #imports

        #rule_enum

        #id_constants

        #rule_enum_impl

        #trait_impls

        #rules_static
    };

    // Prepend header comment as a string since `quote!` strips comments
    let header_comment =
        "// Auto-generated code, DO NOT EDIT DIRECTLY!\n// To regenerate: `cargo lintgen`\n\n";
    format!("{header_comment}{tokens}")
}

/// Create an identifier from a rule entry for the enum variant name.
/// e.g., `eslint::no_debugger` -> `EslintNoDebugger`
fn make_enum_ident(rule: &RuleEntry<'_>) -> Ident {
    let name = format!(
        "{}{}",
        rule.plugin_module_name.to_case(Case::Pascal),
        rule.rule_module_name.to_case(Case::Pascal)
    );
    Ident::new(&name, Span::call_site())
}

/// Create an identifier for the rule's ID constant.
/// e.g., `eslint::no_debugger` -> `ESLINT_NO_DEBUGGER_ID`
fn make_const_ident(rule: &RuleEntry<'_>) -> Ident {
    let name = format!(
        "{}_{}_ID",
        rule.plugin_module_name.to_case(Case::UpperSnake),
        rule.rule_module_name.to_case(Case::UpperSnake)
    );
    Ident::new(&name, Span::call_site())
}

/// Generate constants for rule IDs as consecutive integer literals.
fn generate_id_constants(rule_entries: &[RuleEntry<'_>]) -> TokenStream {
    let constants: Vec<TokenStream> = rule_entries
        .iter()
        .enumerate()
        .map(|(idx, rule)| {
            let const_name = make_const_ident(rule);
            quote! { const #const_name: usize = #idx; }
        })
        .collect();

    quote! { #(#constants)* }
}

fn generate_use_statements(rule_entries: &[RuleEntry<'_>]) -> TokenStream {
    let statements: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let plugin_module = Ident::new(rule.plugin_module_name, Span::call_site());
            let rule_module = Ident::new(rule.rule_module_name, Span::call_site());
            let rule_struct = Ident::new(&rule.rule_struct_name(), Span::call_site());
            let enum_name = make_enum_ident(rule);

            quote! {
                pub use crate::rules::#plugin_module::#rule_module::#rule_struct as #enum_name;
            }
        })
        .collect();

    quote! { #(#statements)* }
}

fn generate_imports() -> TokenStream {
    quote! {
        use crate::{
            context::{ContextHost, LintContext},
            rule::{Rule, RuleCategory, RuleFixMeta, RuleMeta, RuleRunner, RuleRunFunctionsImplemented},
            timing::RuleTimingStat,
            utils::PossibleJestNode,
            AstNode
        };
        #[cfg(feature = "ruledocs")]
        use crate::rule::RuleInfo;
        use oxc_semantic::AstTypesBitset;
    }
}

fn generate_rule_enum(rule_entries: &[RuleEntry<'_>]) -> TokenStream {
    let variants: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { #enum_name(#enum_name) }
        })
        .collect();

    quote! {
        #[derive(Debug, Clone)]
        pub enum RuleEnum {
            #(#variants),*
        }
    }
}

fn generate_rule_enum_impl(rule_entries: &[RuleEntry<'_>]) -> TokenStream {
    let id_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            let const_name = make_const_ident(rule);
            quote! { Self::#enum_name(_) => #const_name }
        })
        .collect();

    let rule_names: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { #enum_name::NAME }
        })
        .collect();
    let rule_count = rule_entries.len();

    let category_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::CATEGORY }
        })
        .collect();

    let fix_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::FIX }
        })
        .collect();

    let documentation_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::documentation() }
        })
        .collect();

    let schema_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::config_schema(generator).or_else(|| #enum_name::schema(generator)) }
        })
        .collect();

    let plugin_name_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            let plugin_name = rule.plugin_module_name;
            quote! { Self::#enum_name(_) => #plugin_name }
        })
        .collect();

    let from_configuration_arms: Vec<TokenStream> = rule_entries
        .iter()
        .filter(|rule| rule.has_custom_from_configuration)
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => Ok(Self::#enum_name(#enum_name::from_configuration(value)?)) }
        })
        .collect();

    let to_configuration_arms: Vec<TokenStream> = rule_entries
        .iter()
        .filter(|rule| rule.has_custom_to_configuration)
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.to_configuration() }
        })
        .collect();

    let run_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.run(node, ctx) }
        })
        .collect();

    let run_once_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.run_once(ctx) }
        })
        .collect();

    let run_on_jest_node_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.run_on_jest_node(jest_node, ctx) }
        })
        .collect();

    let should_run_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.should_run(ctx) }
        })
        .collect();

    let is_tsgolint_rule_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::IS_TSGOLINT_RULE }
        })
        .collect();

    let version_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::VERSION }
        })
        .collect();

    let has_config_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::HAS_CONFIG }
        })
        .collect();

    let info_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(_) => #enum_name::INFO }
        })
        .collect();

    let types_info_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.types_info() }
        })
        .collect();

    let run_info_arms: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { Self::#enum_name(rule) => rule.run_info() }
        })
        .collect();

    // Whether a rule declares a configuration type (i.e. `config = FooConfig`)

    quote! {
        static RULE_NAMES: [&str; #rule_count] = [#(#rule_names),*];

        impl RuleEnum {
            pub fn id(&self) -> usize {
                match self {
                    #(#id_arms),*
                }
            }

            pub fn name(&self) -> &'static str {
                RULE_NAMES[self.id()]
            }

            pub fn category(&self) -> RuleCategory {
                match self {
                    #(#category_arms),*
                }
            }

            /// This [`Rule`]'s auto-fix capabilities.
            pub fn fix(&self) -> RuleFixMeta {
                match self {
                    #(#fix_arms),*
                }
            }

            #[cfg(feature = "ruledocs")]
            pub fn documentation(&self) -> Option<&'static str> {
                match self {
                    #(#documentation_arms),*
                }
            }

            #[cfg(feature = "ruledocs")]
            pub fn schema(&self, generator: &mut schemars::SchemaGenerator) -> Option<schemars::schema::Schema> {
                match self {
                    #(#schema_arms),*
                }
            }

            pub fn plugin_name(&self) -> &'static str {
                match self {
                    #(#plugin_name_arms),*
                }
            }

            pub fn from_configuration(&self, value: serde_json::Value) -> Result<Self, serde_json::error::Error> {
                match self {
                    #(#from_configuration_arms,)*
                    _ => Ok(RULES[self.id()].clone()),
                }
            }

            pub fn to_configuration(&self) -> Option<Result<serde_json::Value, serde_json::Error>> {
                match self {
                    #(#to_configuration_arms,)*
                    _ => None,
                }
            }

            // The dispatch `match` has one arm per rule, so it is large. Keep it in a
            // single non-generic `#[inline(never)]` helper so the giant `match` is
            // emitted *once*, rather than being duplicated across both arms of the
            // `if TIMINGS` below *and* across both monomorphizations of the
            // `const TIMINGS: bool` parameter (i.e. up to 4 copies per dispatcher).
            // `--timing` is a cold diagnostic path, so paying one direct call on the
            // hot path to share the table is a good size trade.
            #[inline(never)]
            fn run_dispatch<'a>(&self, node: &AstNode<'a>, ctx: &LintContext<'a>) {
                match self {
                    #(#run_arms),*
                }
            }

            pub(crate) fn run<'a, const TIMINGS: bool>(
                &self,
                node: &AstNode<'a>,
                ctx: &LintContext<'a>,
                timing_stat: Option<&mut RuleTimingStat>,
            ) {
                if TIMINGS {
                    timing_stat.expect("missing rule timing stat").time(|| self.run_dispatch(node, ctx));
                } else {
                    self.run_dispatch(node, ctx);
                }
            }

            #[inline(never)]
            fn run_once_dispatch(&self, ctx: &LintContext<'_>) {
                match self {
                    #(#run_once_arms),*
                }
            }

            pub(crate) fn run_once<const TIMINGS: bool>(
                &self,
                ctx: &LintContext<'_>,
                timing_stat: Option<&mut RuleTimingStat>,
            ) {
                if TIMINGS {
                    timing_stat.expect("missing rule timing stat").time(|| self.run_once_dispatch(ctx));
                } else {
                    self.run_once_dispatch(ctx);
                }
            }

            #[inline(never)]
            fn run_on_jest_node_dispatch<'a, 'c>(
                &self,
                jest_node: &PossibleJestNode<'a, 'c>,
                ctx: &'c LintContext<'a>,
            ) {
                match self {
                    #(#run_on_jest_node_arms),*
                }
            }

            pub(crate) fn run_on_jest_node<'a, 'c, const TIMINGS: bool>(
                &self,
                jest_node: &PossibleJestNode<'a, 'c>,
                ctx: &'c LintContext<'a>,
                timing_stat: Option<&mut RuleTimingStat>,
            ) {
                if TIMINGS {
                    timing_stat.expect("missing rule timing stat").time(|| self.run_on_jest_node_dispatch(jest_node, ctx));
                } else {
                    self.run_on_jest_node_dispatch(jest_node, ctx);
                }
            }

            pub(crate) fn should_run(&self, ctx: &ContextHost) -> bool {
                match self {
                    #(#should_run_arms),*
                }
            }

            pub fn is_tsgolint_rule(&self) -> bool {
                match self {
                    #(#is_tsgolint_rule_arms),*
                }
            }

            /// The version of oxlint in which this rule was first available.
            #[cfg(feature = "ruledocs")]
            pub fn version(&self) -> &'static str {
                match self {
                    #(#version_arms),*
                }
            }

            /// Whether this rule declares a configuration type.
            pub fn has_config(&self) -> bool {
                match self {
                    #(#has_config_arms),*
                }
            }

            /// Additional information about this rule.
            #[cfg(feature = "ruledocs")]
            pub fn info(&self) -> RuleInfo {
                match self {
                    #(#info_arms),*
                }
            }

            /// A short, one-line summary of what this rule does.
            #[cfg(feature = "ruledocs")]
            pub fn short_description(&self) -> &'static str {
                self.info().short_description
            }

            pub fn types_info(&self) -> Option<&'static AstTypesBitset> {
                match self {
                    #(#types_info_arms),*
                }
            }

            pub fn run_info(&self) -> RuleRunFunctionsImplemented {
                match self {
                    #(#run_info_arms),*
                }
            }
        }
    }
}

fn generate_trait_impls() -> TokenStream {
    quote! {
        impl std::hash::Hash for RuleEnum {
            fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
                self.id().hash(state);
            }
        }

        impl PartialEq for RuleEnum {
            fn eq(&self, other: &Self) -> bool {
                self.id() == other.id()
            }
        }

        impl Eq for RuleEnum {}

        impl Ord for RuleEnum {
            fn cmp(&self, other: &Self) -> std::cmp::Ordering {
                self.id().cmp(&other.id())
            }
        }

        impl PartialOrd for RuleEnum {
            fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
                Some(self.cmp(other))
            }
        }
    }
}

fn generate_rules_static(rule_entries: &[RuleEntry<'_>]) -> TokenStream {
    let entries: Vec<TokenStream> = rule_entries
        .iter()
        .map(|rule| {
            let enum_name = make_enum_ident(rule);
            quote! { RuleEnum::#enum_name(#enum_name::default()) }
        })
        .collect();

    quote! {
        pub static RULES: std::sync::LazyLock<Vec<RuleEnum>> = std::sync::LazyLock::new(|| vec![
            #(#entries),*
        ]);
    }
}

use syn::{Expr, File, Item, Stmt};

/// Return top-level statements which can affect rule execution.
///
/// Local enum and struct declarations are type declarations, so they must not prevent the node
/// type detectors from recognizing an otherwise top-level narrowing check.
pub fn executable_stmts(block: &syn::Block) -> Vec<&Stmt> {
    block
        .stmts
        .iter()
        .filter(|stmt| !matches!(stmt, Stmt::Item(Item::Enum(_) | Item::Struct(_))))
        .collect()
}

pub fn is_node_kind_call(expr: &Expr) -> bool {
    if let Expr::MethodCall(mc) = expr
        && mc.method == "kind"
        && mc.args.is_empty()
        && let Expr::Path(p) = &*mc.receiver
    {
        return p.path.is_ident("node");
    }
    false
}

/// Extract AstKind variant from something like `AstKind::Variant`
pub fn astkind_variant_from_path(path: &syn::Path) -> Option<String> {
    // Expect `AstKind::Variant`
    if path.segments.len() != 2 {
        return None;
    }
    if path.segments[0].ident != "AstKind" {
        return None;
    }
    Some(path.segments[1].ident.to_string())
}

pub fn find_rule_impl_block<'a>(
    file: &'a File,
    rule_struct_name: &str,
) -> Option<&'a syn::ItemImpl> {
    for item in &file.items {
        let syn::Item::Impl(imp) = item else { continue };
        let ident = match imp.self_ty.as_ref() {
            syn::Type::Path(p) => p.path.get_ident(),
            _ => None,
        };
        if ident.is_some_and(|id| id == rule_struct_name)
            && imp.trait_.as_ref().is_some_and(|(path, _)| path.is_ident("Rule"))
        {
            return Some(imp);
        }
    }
    None
}

pub fn find_impl_function<'a>(
    imp: &'a syn::ItemImpl,
    func_name: &str,
) -> Option<&'a syn::ImplItemFn> {
    for impl_item in &imp.items {
        let syn::ImplItem::Fn(func) = impl_item else { continue };
        if func.sig.ident == func_name {
            return Some(func);
        }
    }
    None
}

use std::{
    fmt::Write as _,
    fs::File,
    io::{self, Write},
    path::Path,
    sync::Arc,
};

use rustc_hash::FxHashMap;

use oxc_allocator::Allocator;
use oxc_linter::{
    ConfigStore, ConfigStoreBuilder, ContextSubHost, ContextSubHostOptions, ExternalPluginStore,
    LintOptions, Linter, ModuleRecord, RuleTimingRecord, RuleTimingStore,
};
use oxc_parser::Parser;
use oxc_semantic::SemanticBuilder;
use oxc_tasks_common::{TestFiles, project_root};

const SNAPSHOT_PATH: &str = "tasks/track_linter_timings/linter_timings.snap";

#[test]
#[cfg(any(coverage, coverage_nightly))]
fn test() {
    run().unwrap();
}

/// # Panics
/// # Errors
pub fn run() -> Result<(), io::Error> {
    let linter = create_linter();
    let rule_timing_store = RuleTimingStore::new();

    for file in TestFiles::complicated().files() {
        let allocator = Allocator::default();
        let parser_ret = Parser::new(&allocator, &file.source_text, file.source_type).parse();
        assert!(parser_ret.diagnostics.is_empty());

        let path = Path::new(&file.file_name);
        let semantic = SemanticBuilder::new_linter().build(&parser_ret.program).semantic;
        let module_record = Arc::new(ModuleRecord::new(path, &parser_ret.module_record, &semantic));

        let _ = linter.run_with_disable_directives::<true>(
            path,
            vec![ContextSubHost::new(
                semantic,
                Arc::clone(&module_record),
                0,
                ContextSubHostOptions::default(),
            )],
            &allocator,
            None,
            Some(&rule_timing_store),
        );
    }

    let mut records = rule_timing_store.collect();
    records.sort_unstable_by(|left, right| {
        left.plugin_name.cmp(&right.plugin_name).then_with(|| left.rule_name.cmp(&right.rule_name))
    });

    write_snapshot(SNAPSHOT_PATH, &format_snapshot(&records))
}

fn create_linter() -> Linter {
    let mut external_plugin_store = ExternalPluginStore::default();
    let lint_config = ConfigStoreBuilder::all().build(&mut external_plugin_store).unwrap();
    Linter::new(
        LintOptions::default(),
        ConfigStore::new(lint_config, FxHashMap::default(), external_plugin_store),
        None,
    )
}

fn format_snapshot(records: &[RuleTimingRecord]) -> String {
    let rule_names = records
        .iter()
        .map(|record| format!("{}/{}", record.plugin_name, record.rule_name))
        .collect::<Vec<_>>();
    let rule_width =
        rule_names.iter().map(String::len).max().unwrap_or("Rule".len()).max("Rule".len());
    let calls_width = records
        .iter()
        .map(|record| record.calls.to_string().len())
        .max()
        .unwrap_or("Calls".len())
        .max("Calls".len());

    let mut output = String::new();
    writeln!(output, "{:<rule_width$} | {:>calls_width$}", "Rule", "Calls").unwrap();
    writeln!(output, "{:-<rule_width$}-+-{:-<calls_width$}", "", "").unwrap();

    for (record, rule_name) in records.iter().zip(rule_names) {
        let calls = record.calls;
        writeln!(output, "{rule_name:<rule_width$} | {calls:>calls_width$}").unwrap();
    }

    output
}

fn write_snapshot(path: &str, out: &str) -> Result<(), io::Error> {
    let mut file = File::create(project_root().join(path))?;
    file.write_all(out.as_bytes())
}

